from pathlib import Path
import ast

ROOT=Path.cwd()
SUB=ROOT/"qseries_v2"/"oracle_execution"
SUB.mkdir(parents=True,exist_ok=True)

MOD=SUB/"oracle_035_positive_opportunity_lifecycle.py"
TEST=ROOT/"test_oracle_035_positive_opportunity_lifecycle.py"
RUN=ROOT/"run_oracle_035_positive_opportunity_lifecycle.py"

MODULE_SOURCE='\nfrom __future__ import annotations\nimport builtins,json,re,threading,time\nfrom pathlib import Path\nfrom qseries_v2.oracle_execution import oracle_034_positive_only_paper_attack_lane as q34\n\nEXECUTION_AUTHORITY=False\nPAPER_ONLY=True\nREAL_MONEY_MOVED=False\nREPORT=Path("runtime_state/oracle/oracle_live_execution/oracle_035_positive_opportunity_lifecycle.json")\n\nRX=re.compile(\n    r"^\\[ORACLE028_EXACT_CURRENT\\] token=(\\S+) slot=(\\d+) dir=(\\S+) "\n    r"size=([0-9.]+) bps=([+-]?[0-9.]+) net=([+-]?\\d+) "\n    r"start_ms=([0-9.]+) materialize_ms=([0-9.]+) scan_ms=([0-9.]+)"\n)\n_lock=threading.Lock()\n_active={}\n_closed=[]\n_original_print=None\n\ndef observe_line(line,now=None):\n    m=RX.match(str(line))\n    if not m:return\n    now=float(time.time() if now is None else now)\n    token,slot,direction,size,bps,net,start,mat,scan=m.groups()\n    bps=float(bps); net=int(net)\n    key=token\n    with _lock:\n        ep=_active.get(key)\n        if net>0:\n            if ep is None:\n                ep={\n                    "token":token,"direction":direction,\n                    "first_positive_epoch":now,"last_positive_epoch":now,\n                    "first_slot":int(slot),"last_slot":int(slot),\n                    "consecutive_positive_updates":0,\n                    "peak_bps":bps,"peak_net_lamports":net,\n                    "last_size_sol":float(size),\n                }\n                _active[key]=ep\n            ep["last_positive_epoch"]=now\n            ep["last_slot"]=int(slot)\n            ep["consecutive_positive_updates"]+=1\n            ep["peak_bps"]=max(float(ep["peak_bps"]),bps)\n            ep["peak_net_lamports"]=max(int(ep["peak_net_lamports"]),net)\n            ep["last_size_sol"]=float(size)\n            ep["direction"]=direction\n        elif ep is not None:\n            ep=dict(ep)\n            ep["closed_epoch"]=now\n            ep["positive_duration_ms"]=max(\n                0.0,(float(ep["last_positive_epoch"])-float(ep["first_positive_epoch"]))*1000.0\n            )\n            _closed.append(ep)\n            del _active[key]\n            builtins.__dict__["print"](\n                "[ORACLE035_LIFECYCLE_CLOSE] token=%s updates=%d peak_bps=%+.2f duration_ms=%.3f"\n                %(token[:10],ep["consecutive_positive_updates"],ep["peak_bps"],ep["positive_duration_ms"]),\n                flush=True,\n            )\n\ndef _hook(*args,**kwargs):\n    line=" ".join(str(x) for x in args)\n    observe_line(line)\n    _original_print(*args,**kwargs)\n\ndef install_hook():\n    global _original_print\n    if _original_print is None:\n        _original_print=builtins.print\n        builtins.print=_hook\n\ndef restore_hook():\n    global _original_print\n    if _original_print is not None:\n        builtins.print=_original_print\n        _original_print=None\n\ndef finalize():\n    now=time.time()\n    with _lock:\n        for token,ep0 in list(_active.items()):\n            ep=dict(ep0)\n            ep["closed_epoch"]=now\n            ep["positive_duration_ms"]=max(\n                0.0,(float(ep["last_positive_epoch"])-float(ep["first_positive_epoch"]))*1000.0\n            )\n            ep["open_at_runtime_end"]=True\n            _closed.append(ep)\n        _active.clear()\n        rows=list(_closed)\n    REPORT.parent.mkdir(parents=True,exist_ok=True)\n    REPORT.write_text(json.dumps({\n        "oracle_build":"ORACLE-035",\n        "episodes":rows,\n        "episode_count":len(rows),\n        "execution_authority":False,\n        "paper_only":True,\n    },indent=2,sort_keys=True),encoding="utf-8")\n    return rows\n\ndef run(seconds=300.0):\n    install_hook()\n    try:\n        print("[ORACLE-035] POSITIVE OPPORTUNITY LIFECYCLE",flush=True)\n        print("[TRACK] consecutive positive updates + lifetime + peak edge",flush=True)\n        print("[BROADCAST] disabled",flush=True)\n        return q34.run(seconds=seconds)\n    finally:\n        restore_hook()\n        rows=finalize()\n        print("[ORACLE035_COMPLETE] episodes=%d report=%s"%(len(rows),REPORT),flush=True)\n'

TEST_SOURCE='\nimport unittest\nfrom qseries_v2.oracle_execution import oracle_035_positive_opportunity_lifecycle as q35\n\nclass T(unittest.TestCase):\n    def setUp(self):\n        q35._active.clear();q35._closed.clear()\n\n    def test_episode(self):\n        q35.observe_line("[ORACLE028_EXACT_CURRENT] token=T slot=1 dir=PUMP_TO_METEORA size=0.010 bps=+10.00 net=+100 start_ms=1.0 materialize_ms=1.0 scan_ms=5.0",1.0)\n        q35.observe_line("[ORACLE028_EXACT_CURRENT] token=T slot=2 dir=PUMP_TO_METEORA size=0.010 bps=+12.00 net=+120 start_ms=1.0 materialize_ms=1.0 scan_ms=5.0",1.2)\n        q35.observe_line("[ORACLE028_EXACT_CURRENT] token=T slot=3 dir=PUMP_TO_METEORA size=0.001 bps=-1.00 net=-10 start_ms=1.0 materialize_ms=1.0 scan_ms=5.0",1.3)\n        self.assertEqual(len(q35._closed),1)\n        self.assertEqual(q35._closed[0]["consecutive_positive_updates"],2)\n        self.assertEqual(q35._closed[0]["peak_bps"],12.0)\n\n    def test_safety(self):\n        self.assertFalse(q35.EXECUTION_AUTHORITY)\n        self.assertTrue(q35.PAPER_ONLY)\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n'

RUN_SOURCE='\nimport argparse\nfrom qseries_v2.oracle_execution.oracle_035_positive_opportunity_lifecycle import run\nif __name__=="__main__":\n    p=argparse.ArgumentParser()\n    p.add_argument("--seconds",type=float,default=300.0)\n    a=p.parse_args()\n    raise SystemExit(run(seconds=a.seconds))\n'

ast.parse(MODULE_SOURCE)
ast.parse(TEST_SOURCE)
ast.parse(RUN_SOURCE)

MOD.write_text(MODULE_SOURCE.lstrip(),encoding="utf-8")
TEST.write_text(TEST_SOURCE.lstrip(),encoding="utf-8")
RUN.write_text(RUN_SOURCE.lstrip(),encoding="utf-8")

print('[PASS] ORACLE-035 positive opportunity lifecycle installed')
print('[TRACK] first/last positive, consecutive updates, peak bps, duration')
print('[BROADCAST] disabled')